const body=document.body,headers=[...document.querySelectorAll('[data-header-design]')],buttons=[...document.querySelectorAll('[data-design]')].filter(el=>el.tagName==='BUTTON');
const descriptions={'1':'紧凑双语标识 · 下滚后收起标语','2':'悬浮圆角栏 · 轻磨砂与柔和底色','3':'品牌与操作分层 · 下滚后收起标语横栏'};
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let current='1',frame=0,animation;
function measure(){const header=headers.find(h=>!h.hidden);if(header)body.style.setProperty('--live-header-h',Math.ceil(header.offsetTop+header.offsetHeight)+'px');}
function select(design,write=true){if(!descriptions[design])design='1';current=design;headers.forEach(h=>h.hidden=h.dataset.headerDesign!==design);buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.design===design)));body.dataset.design=design;document.getElementById('hdDescription').textContent=descriptions[design];animation?.cancel();if(!reduced.matches)animation=headers.find(h=>!h.hidden).animate([{opacity:.25,translate:'0 -6px'},{opacity:1,translate:'0 0'}],{duration:300,easing:'cubic-bezier(.22,1,.36,1)'});if(write){const url=new URL(location.href);url.searchParams.set('design',design);history.replaceState(null,'',url);}measure();}
buttons.forEach((b,i)=>{b.onclick=()=>select(b.dataset.design);b.onkeydown=e=>{let j;if(e.key==='ArrowRight')j=(i+1)%buttons.length;else if(e.key==='ArrowLeft')j=(i+buttons.length-1)%buttons.length;else return;e.preventDefault();buttons[j].focus();select(buttons[j].dataset.design);};});
function scroll(){if(frame)return;frame=requestAnimationFrame(()=>{frame=0;body.classList.toggle('is-compact',scrollY>90);measure();});}
addEventListener('scroll',scroll,{passive:true});const observer=new ResizeObserver(measure);headers.forEach(h=>observer.observe(h));
const dialog=document.getElementById('hdPracticeDialog');document.querySelectorAll('[data-hd-practice]').forEach(b=>b.onclick=()=>dialog.showModal());document.getElementById('hdClose').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function links(market){document.querySelectorAll('[data-hd-screen]').forEach(a=>a.href=market==='fund'?'/funds.html':'#stock-picks');document.querySelectorAll('[data-hd-compare]').forEach(a=>a.href=market==='fund'?'/compare.html':'/stock-peers.html?market='+market);}
document.addEventListener('demo:market',e=>links(e.detail.market));links(document.querySelector('[data-home-market][aria-selected=true]')?.dataset.homeMarket||'cn');
document.getElementById('hdTop').onclick=()=>window.scrollTo({top:0,behavior:reduced.matches?'instant':'smooth'});
addEventListener('popstate',()=>select(new URL(location.href).searchParams.get('design'),false));select(new URL(location.href).searchParams.get('design'),false);scroll();
